/*
 * mc64_async_fifo -- a dual-clock FIFO, one word wide, gray-pointer pair.
 *
 * The same structure core_top.v already carries inline for the cartridge
 * loader, lifted out so the save-state path can use it twice (one FIFO per
 * direction) without copying the pointer arithmetic twice more.
 *
 * WHY THIS AND NOT A dcfifo MEGAFUNCTION. The APF framework's own streamers
 * (data_loader/data_unloader, and the save_state_controller in the Agg23 tree)
 * are built on Altera's `dcfifo_mixed_widths`, i.e. on a generated IP file that
 * has to exist in the tree and be regenerated by the IP upgrader. This project
 * never has: the cartridge path replaced exactly that piece with 20 lines of
 * gray pointers (core_top.v, "THE HOST CANNOT BE PACED"), and the fit and every
 * simulation here build the same one definition because there is no IP file to
 * drift. The state FIFOs are the same problem -- one clock on each side, and a
 * burst on one side that the other has to absorb -- so they are the same
 * answer.
 *
 * THE SHAPE. Only one bit of a gray-coded pointer changes per step, so a
 * pointer caught mid-change by the other domain reads as either its old or its
 * new value, never as a third one; the data of an entry is written on the same
 * edge that publishes the pointer, so the consumer is always a full
 * synchroniser delay behind the data being valid. `full` is computed on the
 * write side from the synchronised read pointer, `empty` on the read side from
 * the synchronised write pointer -- each side can therefore push/pop with its
 * own clock alone, and no side ever needs the other's flag.
 *
 * OCCUPANCY. `wcount`/`rcount` are binary (not gray) differences against the
 * synchronised pointer on the same side, so a consumer can tell "how many
 * words are in there" without a second handshake. They lead the truth by up to
 * one entry (the synchroniser), which is all a "has the stream drained" test
 * needs: it is only ever read as count == 0 in a state where nothing is being
 * pushed any more.
 *
 * NO `default_nettype none` RESET SHAPE: `wrst` and `rrst` are synchronous to
 * their own side and must be used together (resetting one side alone desyncs
 * the pointer pair, and the FIFO then looks non-empty forever). In this design
 * they are tied to the power-on reset of the domain that owns them, which both
 * sides see at once because they come from the same PLL-locked condition.
 */
`default_nettype none
`timescale 1ns / 1ps

module mc64_async_fifo #(
    parameter int WIDTH = 64,
    parameter int AW    = 8      // 2^AW entries
) (
    // ---- the producer's side ----
    input  logic             wclk,
    input  logic             wrst,
    input  logic             wr,
    input  logic [WIDTH-1:0] wdata,
    output logic             wfull,
    output logic [AW:0]      wcount,

    // ---- the consumer's side ----
    input  logic             rclk,
    input  logic             rrst,
    input  logic             rd,
    output logic [WIDTH-1:0] rdata,
    output logic             rempty,
    output logic [AW:0]      rcount
);

    localparam int N = 1 << AW;

    logic [WIDTH-1:0] mem [0:N-1];

    logic [AW:0] wbin = '0, wgray = '0;
    logic [AW:0] rbin = '0, rgray = '0;

    logic [AW:0] wbin_n, wgray_n, rbin_n, rgray_n;

    assign wbin_n  = wbin + 1'b1;
    assign wgray_n = (wbin_n >> 1) ^ wbin_n;
    assign rbin_n  = rbin + 1'b1;
    assign rgray_n = (rbin_n >> 1) ^ rbin_n;

    // ---- the two crossings, two flops each ----
    logic [AW:0] rgray_s1 = '0, rgray_s2 = '0;   // read pointer -> write side
    logic [AW:0] wgray_s1 = '0, wgray_s2 = '0;   // write pointer -> read side

    always_ff @(posedge wclk) begin
        rgray_s1 <= rgray;
        rgray_s2 <= rgray_s1;
    end

    always_ff @(posedge rclk) begin
        wgray_s1 <= wgray;
        wgray_s2 <= wgray_s1;
    end

    // Full is "the next write pointer would land on the reader's pointer one
    // lap away": the top two bits inverted, the rest equal -- the standard
    // comparison for a gray pointer with one extra bit.
    logic [AW:0] full_cmp;
    assign full_cmp = {~rgray_s2[AW], ~rgray_s2[AW-1], rgray_s2[AW-2:0]};

    assign wfull  = (wgray_n == full_cmp);
    assign rempty = (rgray == wgray_s2);

    // Binary occupancy: the local pointer minus the synchronised remote one,
    // so the remote pointer has to be converted back out of gray first -- one
    // running XOR from the top bit down, which is a loop and not a shift. (The
    // extra bit is included, so the subtraction cannot borrow out of the
    // pointer's real range.)
    logic [AW:0] rbin_w, wbin_r;

    always_comb begin
        rbin_w[AW] = rgray_s2[AW];
        wbin_r[AW] = wgray_s2[AW];
        for (int i = AW - 1; i >= 0; i--) begin
            rbin_w[i] = rbin_w[i+1] ^ rgray_s2[i];
            wbin_r[i] = wbin_r[i+1] ^ wgray_s2[i];
        end
    end

    assign wcount = wbin - rbin_w;
    assign rcount = wbin_r - rbin;

    always_ff @(posedge wclk) begin
        if (wrst) begin
            wbin  <= '0;
            wgray <= '0;
        end else if (wr && !wfull) begin
            mem[wbin[AW-1:0]] <= wdata;
            wbin  <= wbin_n;
            wgray <= wgray_n;
        end
    end

    always_ff @(posedge rclk) begin
        if (rrst) begin
            rbin  <= '0;
            rgray <= '0;
        end else if (rd && !rempty) begin
            rbin  <= rbin_n;
            rgray <= rgray_n;
        end
    end

    assign rdata = mem[rbin[AW-1:0]];

endmodule
